SELECT production_line_id, production_line_name, factory_id FROM metal_production_line
WHERE factory_id IN #{id}
ORDER BY production_line_id

SELECT production_line_id, production_line_name, factory_id FROM metal_production_line
WHERE factory_id IS NULL OR factory_id=#{factoryId}
ORDER BY production_line_id

SELECT production_line_id, production_line_name, factory_id FROM metal_production_line
WHERE 1=0
OR factory_id=#{factoryId}

  OR production_line_id IN #{id}

ORDER BY production_line_id FOR UPDATE

