UPDATE metal_factory SET factory_name=#{form.factoryName},area=#{form.area},address=#{form.address},
introduction=#{form.introduction},update_by=#{actor},update_time=NOW(),version=version+1
WHERE factory_id=#{form.factoryId} AND del_flag='0' AND version=#{form.version}

UPDATE metal_production_line SET factory_id=#{factoryId},version=version+1,update_time=NOW()
WHERE production_line_id IN #{id}
AND (factory_id IS NULL OR factory_id=#{factoryId})
